export function assertDedicatedIpStateAllowsTenantDeletion(item) {
  const mode = item?.mode?.S || 'shared';
  const resources = item?.resources?.M || {};
  if (mode === 'shared' && Object.keys(resources).length === 0) return;

  const error = new Error(
    'Dedicated IP resources must be cleaned up before deleting this tenant.',
  );
  error.statusCode = 409;
  error.code = 'DEDICATED_IP_CLEANUP_REQUIRED';
  throw error;
}
